+// Reproduction for urfave/cli#2176: nil pointer dereference due to the
+// global HelpFlag when Command.Run is called from parallel goroutines.
+// Test body is the reporter's verbatim, plus a stack trace on panic.
+package debug_test
+
+import (
+	"context"
+	"fmt"
+	"runtime/debug"
+	"testing"
+
+	"github.com/urfave/cli/v3"
+)
+
+func RunCli(args []string) {
+	cmd := &cli.Command{
+		Name:  "debug",
+		Usage: "make an explosive entrance",
+		Action: func(_ context.Context, cmd *cli.Command) error {
+			return nil
+		},
+	}
+
+	if err := cmd.Run(context.Background(), args); err != nil {
+		fmt.Printf("%s\n", err)
+	}
+}
+
+type Case struct {
+	Name string
+	Args []string
+	Exit int
+}
+
+func Test_run(t *testing.T) {
+	t.Parallel()
+
+	tests := []Case{
+		{
+			Name: "hello_world",
+			Exit: 0,
+		},
+		{
+			Name: "hello_sunshine",
+			Exit: 0,
+		},
+	}
+	for _, tt := range tests {
+		t.Run(tt.Name, func(t *testing.T) {
+			t.Parallel()
+
+			defer func() {
+				if r := recover(); r != nil {
+					t.Errorf("unexpected panic - '%s' passing %s\n%s", r, tt.Args, debug.Stack())
+				}
+			}()
+
+			RunCli(tt.Args)
+		})
+	}
+}
